from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="Task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        created_at=created_at or NOW - timedelta(hours=id),
        tags=tags or [],
    )


@pytest.fixture
def sample_tasks():
    return [
        _task(1, "Buy groceries", tags=[Tag("shopping")]),
        _task(2, "Write report", status=TaskStatus.DONE, tags=[Tag("work")]),
        _task(3, "Fix bug", priority=TaskPriority.HIGH, tags=[Tag("work"), Tag("urgent")]),
        _task(4, "Read book", priority=TaskPriority.LOW,
              due_at=NOW - timedelta(days=1)),  # overdue
        _task(5, "Plan meeting", due_at=NOW + timedelta(days=1), tags=[Tag("work")]),
    ]


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_limit_zero_raises(self):
        with pytest.raises(TaskQueryError, match="limit must be an integer"):
            TaskQuery(limit=0)

    def test_limit_over_100_raises(self):
        with pytest.raises(TaskQueryError, match="limit must be an integer"):
            TaskQuery(limit=101)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset must be a non-negative integer"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


class TestFilterStatus:
    def test_filter_pending(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_filter_done(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert all(t.status == TaskStatus.DONE for t in page.items)
        assert page.total == 1


class TestFilterTag:
    def test_filter_by_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="work"), NOW)
        assert page.total == 3
        assert all(any(t.name == "work" for t in task.tags) for task in page.items)

    def test_filter_by_nonexistent_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="nonexistent"), NOW)
        assert page.total == 0


class TestFilterSearch:
    def test_search_case_insensitive(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 1
        assert page.items[0].title == "Buy groceries"

