        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_title_desc(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower, reverse=True)

    def test_sort_by_priority(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(sort="priority"), NOW)
        assert page.items[0].priority == TaskPriority.HIGH

    def test_sort_by_due_at(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(sort="due_at"), NOW)
        # Tasks with due_at set come first; None due_at sorts last
        due_tasks = [t for t in page.items if t.due_at is not None]
        none_tasks = [t for t in page.items if t.due_at is None]
        assert all(t.due_at is not None for t in page.items[:len(due_tasks)])

    def test_sort_by_created_at(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(sort="created_at"), NOW)
        dates = [t.created_at for t in page.items]
        assert dates == sorted(dates)


