    def test_limit(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(limit=2, offset=3), NOW)
        assert len(page.items) == 2
        assert page.offset == 3
        assert page.has_more is False

    def test_offset_beyond_total(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.has_more is False

    def test_has_more_exact_boundary(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(limit=5), NOW)
        assert page.has_more is False


