from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api import InMemoryTaskRepository, normalize_tags
from tasks_api.models import Tag, Task, TaskStatus


NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id: int, title: str = "Test") -> Task:
    return Task(id=id, title=title, created_at=NOW)


class TestInMemoryTaskRepository:
    def test_add_and_get(self, memory_repo):
        task = _make_task(1)
        memory_repo.add(task)
        assert memory_repo.get(1) == task

    def test_get_nonexistent_returns_none(self, memory_repo):
        assert memory_repo.get(99) is None

    def test_add_duplicate_id_raises(self, memory_repo):
        memory_repo.add(_make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            memory_repo.add(_make_task(1, "Other"))

    def test_list_returns_all(self, memory_repo):
        memory_repo.add(_make_task(1))
        memory_repo.add(_make_task(2))
        tasks = list(memory_repo.list())
        assert len(tasks) == 2

    def test_list_empty(self, memory_repo):
        assert list(memory_repo.list()) == []

    def test_update_existing(self, memory_repo):
        task = _make_task(1, "Original")
        memory_repo.add(task)
        task.title = "Updated"
        memory_repo.update(task)
        assert memory_repo.get(1).title == "Updated"

    def test_update_nonexistent_raises(self, memory_repo):
        with pytest.raises(KeyError):
            memory_repo.update(_make_task(99))

    def test_delete_existing(self, memory_repo):
        memory_repo.add(_make_task(1))
        assert memory_repo.delete(1) is True
        assert memory_repo.get(1) is None

    def test_delete_nonexistent_returns_false(self, memory_repo):
        assert memory_repo.delete(99) is False

    def test_next_id_increments(self, memory_repo):
        assert memory_repo.next_id() == 1
        assert memory_repo.next_id() == 2
        assert memory_repo.next_id() == 3


class TestNormalizeTags:
    def test_string_inputs(self):
        tags = normalize_tags(["Work", "urgent"])
        assert [t.name for t in tags] == ["work", "urgent"]

    def test_tag_inputs(self):
        tags = normalize_tags([Tag("hello"), Tag("World")])
        assert [t.name for t in tags] == ["hello", "world"]

    def test_deduplication(self):
        tags = normalize_tags(["work", "WORK", "Work"])
        assert len(tags) == 1
        assert tags[0].name == "work"

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

    def test_mixed_tag_and_string(self):
        tags = normalize_tags([Tag("alpha"), "beta", Tag("alpha")])
        assert len(tags) == 2

